  it('summary 在场（轮行含 running）：session id、「运行中」徽章、轮数、token 合计逐项可辨', async () => {
    const runningSummary = summary(EXECUTOR_SESSION, EXECUTOR_REF, [
      turn(11, EXECUTOR_SESSION, 'running'),
